    "SessionStart": [
      {
        "matcher": "startup",
        "hooks": [
          {
            "type": "command",
            "command": "$PYTHON $CLAUDE_PROJECT_DIR/.claude/superclaude/scripts/session_init.py",
            "timeout": 10,
            "once": true
          },
          {
            "type": "command",
            "command": "$PYTHON $CLAUDE_PROJECT_DIR/.claude/superclaude/scripts/memory_staleness.py",
            "timeout": 5,
            "once": true
          }
        ]
      },
      {
        "matcher": "clear|compact|startup",
        "hooks": [
          {
            "type": "command",
            "command": "$PYTHON $CLAUDE_PROJECT_DIR/.claude/superclaude/scripts/context_reset.py",
            "timeout": 5
          },
          {
            "_comment": "[superclaude] notify if pending insights from prior session",
            "type": "command",
            "command": "$PYTHON $CLAUDE_PROJECT_DIR/.claude/superclaude/scripts/insight_writer.py pending-count",
            "timeout": 5
          }
        ]
      }
    ],
    "PreCompact": [
      {
        "hooks": [
          {
            "_comment": "[superclaude] harvest INSIGHT: markers from transcript before compaction",
            "type": "command",
            "command": "$PYTHON $CLAUDE_PROJECT_DIR/.claude/superclaude/scripts/insight_writer.py harvest-from-hook",
            "timeout": 10
          }
        ]
      }
    ],
    "SessionEnd": [
      {
        "hooks": [
          {
            "_comment": "[superclaude] harvest INSIGHT: markers on /clear, /exit, logout",
            "type": "command",
            "command": "$PYTHON $CLAUDE_PROJECT_DIR/.claude/superclaude/scripts/insight_writer.py harvest-from-hook",
            "timeout": 10
          }
        ]
      }
    ],
    "UserPromptSubmit": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "$PYTHON $CLAUDE_PROJECT_DIR/.claude/superclaude/scripts/context_loader.py",
            "timeout": 5
          }
        ]
      }
    ],
    "PreToolUse": [
      {
        "matcher": "Read",
        "hooks": [
          {
            "_comment": "[superclaude] safety \u2014 blocks Read on files >30KB for token conservation",
            "type": "command",
            "command": "$PYTHON $CLAUDE_PROJECT_DIR/.claude/superclaude/scripts/file_size_guard.py",
            "timeout": 5
          }
        ]
      },
      {
        "matcher": "Bash",
        "hooks": [
          {
            "_comment": "[superclaude] safety \u2014 blocks destructive shell commands",
            "type": "command",
            "command": "jq -r '.tool_input.command // empty' | head -1 | grep -qE 'rm\\s+-rf\\s+/\\s*$|rm\\s+-rf\\s+/\\*|git\\s+push\\s+.*--force([^-]|$).*(main|master)' && echo 'BLOCKED: destructive command detected (--force-with-lease is allowed)' >&2 && exit 2 || exit 0",
            "timeout": 5
          }
        ]
      },
      {
        "matcher": "Edit|Write|Bash",
        "hooks": [
          {
            "_comment": "[superclaude] safety \u2014 circuit breaker (SUPERCLAUDE_LOOP_GUARD=0 to disable)",
            "type": "command",
            "command": "$PYTHON $CLAUDE_PROJECT_DIR/.claude/superclaude/scripts/loop_guard.py",
            "timeout": 5
          }
        ]
      }
    ],
    "PostToolUse": [
      {
        "matcher": "Edit|Write",
        "hooks": [
          {
            "type": "command",
            "command": "$PYTHON $CLAUDE_PROJECT_DIR/.claude/superclaude/scripts/prettier_hook.py",
            "timeout": 30
          },
          {
            "_comment": "[superclaude] optional \u2014 set SUPERCLAUDE_AUTO_TEST=0 to disable",
            "type": "command",
            "command": "$PYTHON $CLAUDE_PROJECT_DIR/.claude/superclaude/scripts/test_runner_hook.py",
            "async": true,
            "timeout": 120
          }
        ]
      },
      {
        "matcher": "Edit|Write|Bash",
        "hooks": [
          {
            "_comment": "[superclaude] safety \u2014 circuit breaker records error/success signatures",
            "type": "command",
            "command": "$PYTHON $CLAUDE_PROJECT_DIR/.claude/superclaude/scripts/loop_guard.py",
            "timeout": 5
          }
        ]
      }
    ]
  }
}

